package io.apiplatform.controlplane.incident;

import io.apiplatform.controlplane.web.Dtos.Finding;
import io.apiplatform.controlplane.web.Dtos.TrafficRouteSummary;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Deterministic investigation rules over aggregated traffic. Every finding carries the numbers that triggered it
 * (evidence) and fixed, reviewed investigation steps. Nothing here is generated by a model.
 */
public final class IncidentRules {
    public static final long MIN_REQUESTS = 20;
    public static final double ERROR_RATE_THRESHOLD = 0.05;
    public static final double AUTH_FAILURE_THRESHOLD = 0.20;
    public static final double RATE_LIMIT_THRESHOLD = 0.30;
    public static final double LATENCY_AVG_MS_THRESHOLD = 1000;

    private IncidentRules() {}

    public static List<Finding> evaluate(List<TrafficRouteSummary> routes) {
        List<Finding> out = new ArrayList<>();
        for (TrafficRouteSummary r : routes) {
            if (r.requests() < MIN_REQUESTS) continue; // avoid alerting on tiny samples
            if (r.errorRate() >= ERROR_RATE_THRESHOLD) {
                out.add(new Finding("HIGH_5XX_RATE", r.errorRate() >= 0.25 ? "CRITICAL" : "HIGH", r.route(),
                        "5xx rate is %.1f%% over the window".formatted(r.errorRate() * 100),
                        evidence("requests", r.requests(), "errors5xx", r.errors5xx(), "errorRate", round(r.errorRate())),
                        List.of("Check recent policy/route/target changes for this API (Audit tab) - revert if correlated.",
                                "Check backend target health and circuit-breaker events (Events tab: CIRCUIT_OPEN, TARGET_UNHEALTHY).",
                                "Open Grafana 'Gateway Overview' filtered by route and compare 502 vs 503 vs 504 distribution.",
                                "Follow a failing request by correlation id in logs and traces (Jaeger).")));
            }
            if (r.timeouts() > 0 && (double) r.timeouts() / r.requests() >= 0.02) {
                out.add(new Finding("BACKEND_TIMEOUTS", "HIGH", r.route(),
                        r.timeouts() + " backend timeouts (" + "%.1f%%".formatted(100.0 * r.timeouts() / r.requests()) + ")",
                        evidence("requests", r.requests(), "timeouts", r.timeouts()),
                        List.of("Compare policy timeoutMs with backend p95 latency; a too-tight timeout produces 504s under normal load.",
                                "Check backend saturation: thread pool, DB connection pool, GC pauses.",
                                "Verify retries are not amplifying load (retry storm): compare gateway request count vs backend request count.")));
            }
            if (r.avgLatencyMs() >= LATENCY_AVG_MS_THRESHOLD) {
                out.add(new Finding("ELEVATED_LATENCY", r.avgLatencyMs() >= 3 * LATENCY_AVG_MS_THRESHOLD ? "HIGH" : "MEDIUM", r.route(),
                        "average latency %.0f ms (max %d ms)".formatted(r.avgLatencyMs(), r.maxLatencyMs()),
                        evidence("avgLatencyMs", Math.round(r.avgLatencyMs()), "maxLatencyMs", r.maxLatencyMs(), "requests", r.requests()),
                        List.of("Use p95/p99 (Grafana histogram_quantile) - averages hide tail latency.",
                                "Split gateway overhead from backend time using trace spans.",
                                "Check for a recent release or policy change and compare latency before/after.",
                                "Check DB slow-query log and connection-pool wait time on the backend.")));
            }
            if ((double) r.authFailures() / r.requests() >= AUTH_FAILURE_THRESHOLD) {
                out.add(new Finding("AUTH_FAILURE_SPIKE", "MEDIUM", r.route(),
                        r.authFailures() + " authentication failures",
                        evidence("requests", r.requests(), "authFailures", r.authFailures()),
                        List.of("Determine whether failures come from one consumer (misconfigured/expired key) or many (credential stuffing).",
                                "Check API key expiry/rotation events and recent key revocations.",
                                "If abusive, tighten IP allowlist or rate limit in a reviewed policy change.")));
            }
            if ((double) r.rateLimited() / r.requests() >= RATE_LIMIT_THRESHOLD) {
                out.add(new Finding("RATE_LIMIT_SPIKE", "MEDIUM", r.route(),
                        r.rateLimited() + " requests rejected with 429",
                        evidence("requests", r.requests(), "rateLimited", r.rateLimited()),
                        List.of("Identify the consumer(s) being limited; confirm the limit matches their subscription plan.",
                                "If Redis limiter fell back to local mode, per-instance limits multiply by gateway replica count.",
                                "Decide between raising the limit (reviewed policy change) and contacting the consumer about retries/backoff.")));
            }
        }
        return out;
    }

    /** Operational events map to dedicated findings when they appear in the window. */
    public static Finding fromEventType(String type, String route, long count) {
        return switch (type) {
            case "CIRCUIT_OPEN" -> new Finding("CIRCUIT_BREAKER_OPEN", "HIGH", route, count + " circuit-open event(s)",
                    evidence("events", count),
                    List.of("A backend target crossed the failure threshold; check its health endpoint and recent deploys.",
                            "Requests are failing fast with 503 (graceful degradation) until the half-open probe succeeds."));
            case "SNAPSHOT_STALE" -> new Finding("CONFIG_STALE", "HIGH", route, "gateway could not refresh configuration",
                    evidence("events", count),
                    List.of("Check control-plane availability and the gateway token.",
                            "Gateways keep serving the last-known-good snapshot; policy changes are NOT being applied until recovery."));
            case "INVALID_CONFIG" -> new Finding("INVALID_GATEWAY_CONFIG", "HIGH", route, "gateway rejected a configuration snapshot",
                    evidence("events", count),
                    List.of("Inspect the rejected route/target reason in gateway logs; fix the policy or target and republish.",
                            "The previous valid snapshot remains active."));
            case "POOL_EXHAUSTED" -> new Finding("CONNECTION_POOL_EXHAUSTION", "HIGH", route, count + " pool exhaustion event(s)",
                    evidence("events", count),
                    List.of("Check hikaricp_connections_pending and active vs max.", "Look for long transactions or slow queries holding connections."));
            case "QUEUE_BACKLOG" -> new Finding("QUEUE_BACKLOG", "MEDIUM", route, count + " backlog event(s)",
                    evidence("events", count),
                    List.of("Check telemetry buffer drops at the gateway (dropped batches indicate control-plane slowness).",
                            "Scale the consumer or raise batch size; confirm bounded queues are dropping oldest data, not blocking requests."));
            default -> null;
        };
    }

    private static Map<String, Object> evidence(Object... kv) {
        Map<String, Object> m = new LinkedHashMap<>();
        for (int i = 0; i < kv.length; i += 2) m.put((String) kv[i], kv[i + 1]);
        return m;
    }

    private static double round(double d) { return Math.round(d * 10000.0) / 10000.0; }
}
